const $ = s => document.querySelector(s);
const samples = [
 {id:'example-1',reason:'I like finding patterns.',name:'Example contributor',affiliation:'Example University',category:'hep-th',stage:'PhD',date:'2026-10-06'},
 {id:'example-2',reason:'To understand gravity.',name:'Example contributor',affiliation:'Example University',category:'gr-qc',stage:'Postdoc',date:'2026-10-06'},
 {id:'example-3',reason:'For the questions we cannot answer yet.',name:'Example contributor',affiliation:'Example University',category:'quant-ph',stage:'Faculty',date:'2026-10-06'},
 {id:'example-4',reason:'Because experiments surprise us.',name:'Example contributor',affiliation:'Example University',category:'hep-ex',stage:'Master’s',date:'2026-10-06'},
 {id:'example-5',reason:'To understand where our models fail.',name:'Example contributor',affiliation:'Example University',category:'astro-ph',stage:'Undergrad',date:'2026-10-06'},
 {id:'example-6',reason:'To work through difficult problems.',name:'Example contributor',affiliation:'Example University',category:'cond-mat',stage:'Alumni',date:'2026-10-06'},
 {id:'example-7',reason:'To test what we think we know.',name:'Example contributor',affiliation:'Example University',category:'hep-ph',stage:'PhD',date:'2026-10-05'}
];
const COMMON_CATEGORY_OPTIONS=['astro-ph','cond-mat','gr-qc','hep-ex','hep-ph','hep-th','quant-ph'];
const MORE_CATEGORY_OPTIONS=['hep-lat','math-ph','nucl-ex','nucl-th','physics'];
