const sampleCities=[['Cambridge','United Kingdom',52.2053,0.1218],['Chicago','United States',41.8781,-87.6298],['Zurich','Switzerland',47.3769,8.5417],['Tokyo','Japan',35.6762,139.6503],['Waterloo','Canada',43.4643,-80.5204],['São Paulo','Brazil',-23.5505,-46.6333]];samples.forEach((r,i)=>{[r.city,r.country,r.lat,r.lng]=sampleCities[i%sampleCities.length]});
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function saveStore(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
let config={...window.WALL_CONFIG,...readStore('physics-wall-config',{})}, rows=samples, flagId=null;
let voter=readStore('physics-wall-voter',null);if(!voter){voter=crypto.randomUUID();saveStore('physics-wall-voter',voter)}
let demoHearts=readStore('physics-wall-demo-hearts',{}), previewTiles=[], featuredOffset=0, activeCategories=new Set(), activeStages=new Set(), fieldFiltersOpen=false, sortMode='latest', page=0, pageCount=1;
const PAGE_SIZE=6;
const svgHeart='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg>';
const svgFlag='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 21V3m0 1c5-4 9 4 14 0v10c-5 4-9-4-14 0"/></svg>';
const svgShare='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="18" cy="5" r="2.5"/><circle cx="6" cy="12" r="2.5"/><circle cx="18" cy="19" r="2.5"/><path d="m8.2 10.8 7.6-4.5M8.2 13.2l7.6 4.5"/></svg>';
function endpointValid(url){try{let u=new URL(url);return u.protocol==='https:'&&u.hostname==='script.google.com'&&/^\/macros\/s\/[\w-]+\/exec$/.test(u.pathname)}catch{return false}}
function formValid(url){try{const u=new URL(url);return u.protocol==='https:'&&(u.hostname==='forms.gle'||(u.hostname==='docs.google.com'&&u.pathname.startsWith('/forms/')))}catch{return false}}
function api(action,params={}){return new Promise((resolve,reject)=>{if(!endpointValid(config.endpointUrl))return reject(new Error('Connect the site endpoint first.'));const callback='wallcb'+crypto.randomUUID().replaceAll('-','');const script=document.createElement('script');const url=new URL(config.endpointUrl);Object.entries({action,visitor:voter,callback,...params}).forEach(([k,v])=>url.searchParams.set(k,v));let timer;function clean(){clearTimeout(timer);script.remove();delete window[callback]}window[callback]=data=>{clean();data.ok?resolve(data):reject(new Error(data.error||'Could not complete this request.'))};script.onerror=()=>{clean();reject(new Error('Could not reach the wall. Please try again.'))};timer=setTimeout(()=>{clean();reject(new Error('The wall is taking too long to respond. Please try again.'))},20000);script.src=url.href;document.head.append(script)})}
function text(tag,value,cls){const el=document.createElement(tag);el.textContent=value;if(cls)el.className=cls;return el}
function fitBrandSubtitle(){const title=$('.brand-title'),subtitle=$('.brand-subtitle');if(!title||!subtitle)return;subtitle.style.letterSpacing='0px';const difference=title.getBoundingClientRect().width-subtitle.getBoundingClientRect().width;const gaps=Math.max(1,subtitle.textContent.length-1);subtitle.style.letterSpacing=`${difference/gaps}px`}
function displayDate(value){if(!value)return '';const date=new Date(value+'T12:00:00');return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('en',{day:'numeric',month:'short',year:'numeric'}).format(date)}
function answerClass(r,index=null){if(index!==null)return index%2?'answer-blue':'answer-black';const slot=[...String(r.id)].reduce((sum,char)=>sum+char.charCodeAt(0),0)%2;return slot?'answer-blue':'answer-black'}
function arxivLink(value){const raw=(value||'').trim().replace(/^arxiv:\s*/i,'');if(/^(\d{4}\.\d{4,5}|[a-z-]+(\.[A-Z]{2})?\/\d{7})(v\d+)?$/.test(raw))return 'https://arxiv.org/abs/'+raw;try{const u=new URL(raw);if(u.protocol==='https:'&&u.hostname==='arxiv.org'&&/^\/(a|abs)\/[A-Za-z0-9._/-]+$/.test(u.pathname)&&!u.search&&!u.hash)return u.href}catch{}return null}
function storyUrl(id){const url=new URL(location.href);url.hash='story='+encodeURIComponent(id);return url.href}
async function shareStory(r){const url=storyUrl(r.id),data={title:'Why We Do Physics',text:`“${r.reason}” — ${r.name||'Anonymous'}`,url};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(url);$('#status').textContent='Story link copied.'}}catch(err){if(err.name!=='AbortError')$('#status').textContent='Could not share this story.'}}
function makeTile(r,i,demo,prefix){
 const tile=document.createElement('article');
 tile.id=prefix+'-'+r.id;
 tile.className='tile'+(r.reason.length>110?' long':'');
 tile.classList.add(answerClass(r,i));
 if(r.date)tile.append(text('span',displayDate(r.date),'tile-date'));
 tile.append(text('blockquote',r.reason));
 const credit=text('div',r.name||'Anonymous','credit');
 if(r.affiliation)credit.append(text('span',r.affiliation));
 const location=[r.city,r.country].filter(Boolean).join(', ');if(location)credit.append(text('span',location));
 if(r.year)credit.append(text('span',`PhD ${r.year}`));
 const arxiv=arxivLink(r.arxiv);
 if(arxiv){const link=text('a',arxiv.includes('/a/')?'arXiv profile':'arXiv paper','arxiv');link.href=arxiv;link.target='_blank';link.rel='noopener noreferrer';credit.append(link)}
 tile.append(credit);
 const tagValues=[r.category,r.stage].filter(Boolean);
 if(tagValues.length){const tags=document.createElement('div');tags.className='tags';tagValues.forEach(value=>tags.append(text('span',value)));tile.append(tags)}
 if(r.preview)tile.append(text('span','Your unsent preview','example'));
 const bottom=document.createElement('div');bottom.className='tile-bottom';
 const heart=document.createElement('button'),liked=demo?!!demoHearts[r.id]:!!r.liked;
 heart.setAttribute('aria-pressed',String(liked));heart.setAttribute('aria-label',`${liked?'Remove heart from':'Heart'} response by ${r.name}`);heart.innerHTML=svgHeart;heart.append(text('span',demo?(liked?1:0):(r.hearts||0)));
 heart.onclick=async()=>{if(demo){demoHearts[r.id]=!liked;saveStore('physics-wall-demo-hearts',demoHearts);render();return}heart.disabled=true;try{const result=await api('heart',{id:r.id,liked:!liked});r.hearts=result.hearts;r.liked=result.liked;render();$('#status').textContent=''}catch(e){$('#status').textContent=e.message;heart.disabled=false}};
 const share=document.createElement('button');share.className='share';share.innerHTML=svgShare;share.title='Share';share.setAttribute('aria-label',`Share response by ${r.name||'Anonymous'}`);share.onclick=()=>shareStory(r);
 const flag=document.createElement('button');flag.className='flag';flag.innerHTML=svgFlag;flag.title='Flag';flag.setAttribute('aria-label',`Flag response by ${r.name}`);flag.onclick=()=>{flagId=r.id;$('#flag-status').textContent='';$('#flag-form').hidden=false;$('#flag-dialog').showModal()};
 bottom.append(heart,share,flag);tile.append(bottom);return tile;
}
function toggleSelection(set,value){set.has(value)?set.delete(value):set.add(value);page=0;render()}
function renderFilters(){const root=$('#filter-chips');root.replaceChildren();const common=document.createElement('div');common.className='filter-chip-row';for(const value of COMMON_CATEGORY_OPTIONS){const chip=text('button',value,'filter-chip');chip.type='button';chip.setAttribute('aria-pressed',String(activeCategories.has(value)));chip.onclick=()=>toggleSelection(activeCategories,value);common.append(chip)}const expand=text('button',fieldFiltersOpen?'−':'+','filter-expand');expand.type='button';expand.setAttribute('aria-expanded',String(fieldFiltersOpen));expand.setAttribute('aria-label',fieldFiltersOpen?'Hide more arXiv fields':'Show more arXiv fields');expand.onclick=()=>{fieldFiltersOpen=!fieldFiltersOpen;if(!fieldFiltersOpen)MORE_CATEGORY_OPTIONS.forEach(value=>activeCategories.delete(value));page=0;render()};common.append(expand);root.append(common);if(fieldFiltersOpen){const more=document.createElement('div');more.className='filter-chip-row filter-field-row';for(const value of MORE_CATEGORY_OPTIONS){const chip=text('button',value,'filter-chip');chip.type='button';chip.setAttribute('aria-pressed',String(activeCategories.has(value)));chip.onclick=()=>toggleSelection(activeCategories,value);more.append(chip)}root.append(more)}const stages=document.createElement('div');stages.className='filter-chip-row filter-stage-row';for(const value of STAGE_OPTIONS){const chip=text('button',value,'filter-chip');chip.type='button';chip.setAttribute('aria-pressed',String(activeStages.has(value)));chip.onclick=()=>toggleSelection(activeStages,value);stages.append(chip)}if(activeCategories.size||activeStages.size){const clear=text('button','clear','filter-clear');clear.type='button';clear.onclick=()=>{activeCategories.clear();activeStages.clear();fieldFiltersOpen=false;page=0;render()};stages.append(clear)}root.append(stages)}
function render(){const wall=$('#wall'),featured=$('#featured');wall.replaceChildren();featured.replaceChildren();const demo=!config.endpointUrl;const all=demo?[...samples,...previewTiles]:rows;const query=($('#search-input').value||'').toLocaleLowerCase().trim();const matches=all.filter(r=>(!activeCategories.size||activeCategories.has(r.category))&&(!activeStages.size||activeStages.has(r.stage))&&[r.reason,r.name,r.affiliation,r.year,r.arxiv,r.city,r.country,r.category,r.stage].join(' ').toLocaleLowerCase().includes(query));const list=[...matches].sort((a,b)=>sortMode==='liked'?((demoHearts[b.id]?1:0)+(b.hearts||0))-((demoHearts[a.id]?1:0)+(a.hearts||0)):String(b.date||'').localeCompare(String(a.date||'')));renderFilters();const countries=new Set(list.map(r=>r.country).filter(Boolean)).size;$('#response-tally').textContent=`${list.length} ${list.length===1?'response':'responses'} · ${countries} ${countries===1?'country':'countries'}`;$('#search-count').textContent=query?`${list.length} of ${all.length} responses`:'';$('#count').textContent=all.length;$('#count-label').textContent=demo?'example responses':all.length===1?'response':'responses';$('#mode').textContent=demo?'Preview · illustrative responses':'Community responses';$('#sort-latest').setAttribute('aria-pressed',String(sortMode==='latest'));$('#sort-liked').setAttribute('aria-pressed',String(sortMode==='liked'));const featuredRows=all.length?[all[featuredOffset%all.length]]:[];featuredRows.forEach(r=>featured.append(makeTile(r,featuredOffset,demo,'featured')));pageCount=Math.max(1,Math.ceil(list.length/PAGE_SIZE));page=Math.min(page,pageCount-1);const pageRows=list.slice(page*PAGE_SIZE,(page+1)*PAGE_SIZE);for(const [i,r]of pageRows.entries())wall.append(makeTile(r,page*PAGE_SIZE+i,demo,'tile'));if(!list.length)wall.append(text('p',query?'No responses match your search.':'Waiting for the first response.'));const pager=document.querySelector('.pager');pager.hidden=pageCount<=1;$('#page-count').textContent=`${page+1}/${pageCount}`;$('#page-prev').disabled=page===0;$('#page-next').disabled=page>=pageCount-1;renderClouds(list);const shared=decodeURIComponent((location.hash.match(/^#story=(.*)$/)||[])[1]||'');if(shared)queueMicrotask(()=>document.getElementById('tile-'+CSS.escape(shared))?.scrollIntoView({block:'center'}))}
async function load(){if(!config.endpointUrl){$('#status').textContent='';render();return}$('#status').textContent='Loading…';try{const data=await api('wall');rows=data.rows;render();$('#status').textContent=''}catch(e){rows=[];render();$('#mode').textContent='Connection unavailable';$('#status').textContent=e.message}}
for(const button of document.querySelectorAll('.close'))button.onclick=()=>button.closest('dialog').close();for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
$('#contribute').onclick=()=>$('#submit-dialog').showModal();
$('#preview-form').onsubmit=async e=>{e.preventDefault();const form=e.target,f=new FormData(form),entry={id:'preview-'+crypto.randomUUID(),name:f.get('name'),affiliation:f.get('affiliation'),stage:f.get('stage'),category:f.get('category'),year:f.get('year'),reason:f.get('reason'),arxiv:f.get('arxiv'),city:f.get('mapOptIn')?f.get('city'):'',country:f.get('mapOptIn')?f.get('country'):'',preview:true};if(!endpointValid(config.endpointUrl)){previewTiles.push(entry);$('#submit-dialog').close();render();form.reset();reasonCount.textContent='0 / 140';syncMapFields();return}const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const params=new URLSearchParams({action:'submit',name:entry.name,affiliation:entry.affiliation,stage:entry.stage,category:entry.category,year:entry.year,reason:entry.reason,arxiv:entry.arxiv,city:entry.city,country:entry.country,mapOptIn:f.get('mapOptIn')?'yes':'',consent:f.get('consent')?'yes':'',website:f.get('website')||''});await fetch(config.endpointUrl,{method:'POST',mode:'no-cors',body:params});$('#submit-dialog').close();form.reset();reasonCount.textContent='0 / 140';syncMapFields();$('#status').textContent='Received for review.'}catch{$('#form-message').textContent='Could not send. Please try again.'}finally{button.disabled=false}};
$('#flag-form').onsubmit=async e=>{e.preventDefault();if(!config.endpointUrl){$('#flag-status').textContent='Preview only. No report was sent. Connected responses send flags privately to the moderator.';return}const b=e.target.querySelector('button');b.disabled=true;try{await api('flag',{id:flagId,reason:$('#flag-reason').value});$('#flag-status').textContent='Flag received. The moderator can review it.';$('#flag-form').hidden=true}catch(err){$('#flag-status').textContent=err.message}finally{b.disabled=false}};
load();setInterval(()=>{if(config.endpointUrl&&!document.hidden&&!document.querySelector('dialog[open]'))load()},60000);

function renderClouds(list){
 const root=$('#clouds'),pins=$('#map-pins'),lines=$('#map-lines');root.replaceChildren();pins.replaceChildren();lines.replaceChildren();
 const located=list.filter(r=>Number.isFinite(r.lat)&&Number.isFinite(r.lng)&&Math.abs(r.lat)<=90&&Math.abs(r.lng)<=180&&r.city);
 $('#map-status').textContent=located.length?`${config.endpointUrl?'':'Example city placements · '}${located.length} ${located.length===1?'declaration':'declarations'} with a shared city. Select a city to read a response.`:'No opted-in city locations to show.';
 const occupied=[];
 function showCloud(r,clear=false,slot=null){if(clear){root.replaceChildren();lines.replaceChildren();occupied.length=0}const px=(r.lng+180)/360*100,py=(90-r.lat)/180*100,laneX=[2,37.5,73];let x,y,edgeY;if(slot===null){x=Math.min(72,Math.max(1,px+2));y=py<50?58:4;edgeY=py<50?y:y+30}else{x=laneX[slot%laneX.length];y=py<50?58:4;edgeY=py<50?y:y+30}occupied.push([x,y]);const cloud=document.createElement('button');cloud.className='cloud';cloud.style.left=x+'%';cloud.style.top=y+'%';cloud.append(text('blockquote',r.reason.length>100?r.reason.slice(0,97)+'…':r.reason),text('span',`${r.name} · ${r.city}, ${r.country}`));cloud.setAttribute('aria-label',`Read declaration by ${r.name} in ${r.city}`);cloud.onclick=()=>{const tile=document.getElementById('tile-'+r.id);tile.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});tile.classList.add('highlight');setTimeout(()=>tile.classList.remove('highlight'),2500)};const line=document.createElementNS('http://www.w3.org/2000/svg','line');for(const [k,v]of Object.entries({x1:px*10,y1:py*5,x2:(x+12.5)*10,y2:edgeY*5,stroke:'#0056b3','stroke-width':'1',opacity:'.28','stroke-linecap':'round'}))line.setAttribute(k,v);lines.append(line);root.append(cloud)}
 const cities=new Map();located.forEach(r=>{const key=[r.lat,r.lng].join(',');if(!cities.has(key))cities.set(key,[]);cities.get(key).push(r)});
 for(const group of cities.values()){const r=group[0],pin=document.createElement('button');pin.className='map-pin';pin.style.left=((r.lng+180)/360*100)+'%';pin.style.top=((90-r.lat)/180*100)+'%';pin.setAttribute('aria-label',`${r.city}, ${r.country}: ${group.length} ${group.length===1?'declaration':'declarations'}`);pin.title=pin.getAttribute('aria-label');let index=0;pin.onclick=()=>{showCloud(group[index%group.length],true);index++};pins.append(pin)}
 const candidates=[...cities.values()].map(group=>group[0]),chosen=[];if(candidates.length)chosen.push(candidates[0]);while(chosen.length<Math.min(3,candidates.length)){const remaining=candidates.filter(r=>!chosen.includes(r));remaining.sort((a,b)=>Math.min(...chosen.map(c=>(a.lat-c.lat)**2+((a.lng-c.lng)*Math.cos((a.lat+c.lat)*Math.PI/360))**2))-Math.min(...chosen.map(c=>(b.lat-c.lat)**2+((b.lng-c.lng)*Math.cos((b.lat+c.lat)*Math.PI/360))**2)));chosen.push(remaining.at(-1))}chosen.sort((a,b)=>a.lng-b.lng).forEach((r,i)=>showCloud(r,false,i));
}
$('#about').onclick=()=>$('#about-dialog').showModal();
$('#search-input').oninput=()=>{page=0;render()};
function stepFeatured(delta){const all=config.endpointUrl?rows:[...samples,...previewTiles];if(!all.length)return;featuredOffset=(featuredOffset+delta+all.length)%all.length;render()}
$('#featured-prev').onclick=()=>stepFeatured(-1);$('#featured-next').onclick=()=>stepFeatured(1);
function setSort(mode){sortMode=mode;page=0;render()}$('#sort-latest').onclick=()=>setSort('latest');$('#sort-liked').onclick=()=>setSort('liked');
function setPage(next){page=next;render();document.querySelector('.wall-section').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}$('#page-prev').onclick=()=>setPage(Math.max(0,page-1));$('#page-next').onclick=()=>setPage(page+1);
const reasonInput=document.querySelector('textarea[name="reason"]'),reasonCount=$('#reason-count'),mapOptIn=document.querySelector('input[name="mapOptIn"]'),locationFields=$('#location-fields');
function syncMapFields(){const enabled=mapOptIn.checked;locationFields.hidden=!enabled;mapOptIn.setAttribute('aria-expanded',String(enabled));for(const input of locationFields.querySelectorAll('input'))input.required=enabled}
reasonInput.oninput=()=>reasonCount.textContent=`${reasonInput.value.length} / 140`;mapOptIn.onchange=syncMapFields;syncMapFields();
