render();
let cloudResize;window.addEventListener('resize',()=>{fitBrandSubtitle();clearTimeout(cloudResize);cloudResize=setTimeout(render,200)});fitBrandSubtitle();document.fonts?.ready.then(fitBrandSubtitle);
